; Enemy altitude marks and the status line colour
; $6862-$68fc

; Shows the altitude of the enemy plane relative to the plane, and sets the status line colour $4052 for the altitude.
update_altitude_alert
        lda #$00
        sta $0c27
        sta $0c4f
        lda #$20                        ; Space on the two mark positions of the status line.
        sta $0f96
        sta $0fbe
        lda enemy_timer                 ; $4041 = 0 and $4051 = 0: an enemy plane flies.
        bne update_altitude_alert_ground
        lda enemy_explode_timer
        bne update_altitude_alert_ground
        lda altitude                    ; Same altitude: the enemy altitude $4044 is from altitude -3 to altitude +4.
        clc
        adc #$04
        cmp enemy_altitude
        bcc update_altitude_alert_above
        sbc #$08
        cmp enemy_altitude
        bcs update_altitude_alert_below
        jmp update_altitude_alert_level
update_altitude_alert_above
        lda #$2d                        ; Mark $2d: the enemy plane is higher.
        sta $0f96
        jmp update_altitude_alert_ground
update_altitude_alert_below
        lda #$2e                        ; Mark $2e: the enemy plane is lower.
        sta $0fbe
        jmp update_altitude_alert_ground
update_altitude_alert_level
        lda #$0e                        ; Colour $0e (light blue): same altitude.
        sta status_bg_colour
        rts
update_altitude_alert_ground
        lda altitude                    ; Altitude below 0: crash ($4050 = 1) and altitude 0.
        bpl update_altitude_alert_low
        lda #$01
        sta crash_flag
        lda #$00
        sta altitude
update_altitude_alert_low
        lda #$00
        sta low_flight                  ; $406f = 0: the plane is not low; the bullet does not hit ground objects.
        lda altitude
        cmp #$1a                        ; Altitude 26 and up: colour 0.
        bcc update_altitude_alert_obstacle
        lda #$00
        sta status_bg_colour
        rts
update_altitude_alert_obstacle
        lda #$09                        ; Altitude below 26: colour 9 and $406f = 9 (low).
        sta low_flight
        sta status_bg_colour
        lda obstacle_altitude           ; $40a2 = obstacle height: at or below it, the colour flashes yellow.
        cmp altitude
        bcc update_altitude_alert_state
        lda frame_count
        and #$10
        beq update_altitude_alert_clear
        lda #$07
        sta status_bg_colour
        jmp update_altitude_alert_state
update_altitude_alert_clear
        lda #$00
        sta status_bg_colour
        rts
update_altitude_alert_state
        lda plane_state                 ; Ground states 1, 4 and 5 (runway): colour 0.
        cmp #$01
        beq update_altitude_alert_clear
        cmp #$04
        beq update_altitude_alert_clear
        cmp #$05
        beq update_altitude_alert_clear
        rts
